create table if not exists public.draft_approval_runs ( id uuid primary key default gen_random_uuid(), status text not null default 'running' check (status in ('running', 'finished', 'cancelled', 'failed')), total integer not null default 0, approved integer not null default 0, failed integer not null default 0, first_error text, failed_ids uuid[] not null default '{}', ticks integer not null default 0, claimed_at timestamptz, started_by text not null, started_at timestamptz not null default timezone('utc', now()), finished_at timestamptz, status_reason text );
create index if not exists draft_approval_runs_status_idx on public.draft_approval_runs (status, started_at desc);
comment on table public.draft_approval_runs is 'One press of Approve all, carried on by cron. Admin-only: it is a record of our own review work.';
alter table public.draft_approval_runs enable row level security;
do $$ begin create policy "Admins manage draft approval runs" on public.draft_approval_runs for all using (public.is_admin()) with check (public.is_admin()); exception when duplicate_object then null; end; $$;
create or replace function public.draft_approval_batch( p_limit integer default 25, p_exclude uuid[] default '{}' ) returns table ( id uuid, domain text, email_id uuid, matched_website_id uuid, proposed jsonb ) language sql stable security definer set search_path = public as $$ with contested as ( select c.domain from public.listing_drafts c where c.status in ('pending', 'approved') group by c.domain having count(*) > 1 ) select d.id, d.domain, d.email_id, d.matched_website_id, d.proposed from public.listing_drafts d where d.status = 'pending' and d.low_confidence_count = 0 and cardinality(d.flags) = 0 and not (d.id = any (p_exclude)) and not exists (select 1 from contested x where x.domain = d.domain) order by d.id asc limit greatest(1, p_limit); $$;
revoke all on function public.draft_approval_batch(integer, uuid[]) from public;
revoke all on function public.draft_approval_batch(integer, uuid[]) from anon;
revoke all on function public.draft_approval_batch(integer, uuid[]) from authenticated;
create or replace function public.draft_approval_eligible_count() returns integer language sql stable security definer set search_path = public as $$ with contested as ( select c.domain from public.listing_drafts c where c.status in ('pending', 'approved') group by c.domain having count(*) > 1 ) select count(*)::integer from public.listing_drafts d where d.status = 'pending' and d.low_confidence_count = 0 and cardinality(d.flags) = 0 and not exists (select 1 from contested x where x.domain = d.domain); $$;
revoke all on function public.draft_approval_eligible_count() from public;
revoke all on function public.draft_approval_eligible_count() from anon;
revoke all on function public.draft_approval_eligible_count() from authenticated;
create or replace function public.claim_draft_approval_run(p_stale_seconds integer default 600) returns uuid language plpgsql volatile security definer set search_path = public as $$ declare v_id uuid; begin update public.draft_approval_runs r set claimed_at = timezone('utc', now()), ticks = r.ticks + 1 where r.id = ( select c.id from public.draft_approval_runs c where c.status = 'running' and ( c.claimed_at is null or c.claimed_at < timezone('utc', now()) - make_interval(secs => greatest(60, p_stale_seconds)) ) order by c.started_at for update skip locked limit 1 ) returning r.id into v_id; return v_id; end; $$;
revoke all on function public.claim_draft_approval_run(integer) from public;
revoke all on function public.claim_draft_approval_run(integer) from anon;
revoke all on function public.claim_draft_approval_run(integer) from authenticated;
